// TSqlParserInit initializes any static state used to implement TSqlParser. By default the
// static state used to implement the parser is lazily initialized during the first call to
// NewTSqlParser(). You can call this function if you wish to initialize the static state ahead
// of time.
func TSqlParserInit() {
	staticData := &TSqlParserParserStaticData
	staticData.once.Do(tsqlparserParserInit)
}

// NewTSqlParser produces a new parser instance for the optional input antlr.TokenStream.
func NewTSqlParser(input antlr.TokenStream) *TSqlParser {
	TSqlParserInit()
	this := new(TSqlParser)
	this.BaseParser = antlr.NewBaseParser(input)
	staticData := &TSqlParserParserStaticData
	this.Interpreter = antlr.NewParserATNSimulator(this, staticData.atn, staticData.decisionToDFA, staticData.PredictionContextCache)
	this.RuleNames = staticData.RuleNames
	this.LiteralNames = staticData.LiteralNames
	this.SymbolicNames = staticData.SymbolicNames
	this.GrammarFileName = "TSqlParser.g4"

	return this
}

